import{_ as e,c as t,o as a,U as i}from"./chunks/framework.DsWckVvh.js";const g=JSON.parse('{"title":"Configuration","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"guide/in-depth/config/index.md","filePath":"guide/in-depth/config/index.md"}'),o={name:"guide/in-depth/config/index.md"},n=i('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Data and configuration for build a visualization are different concerns. In servals cases, we define together data and colors, size, and other configuration properties. It is a good practice to separate data and configuration in data visualization systems.</p><ul><li><p><strong>Reusability</strong>: By separating data from configuration, you can reuse the same visualization with different datasets. This is particularly useful when you create a set of standard visualizations for your application which needs to be populated with different data.</p></li><li><p><strong>Data Integrity</strong>: Separating data and configuration ensures that you are not modifying original data when changing visual aspects like colors or size. This is crucial for maintaining data integrity.</p></li><li><p><strong>Flexibility</strong>: With a separate configuration, you can easily adjust the size, color, and other parameters without affecting the data. This makes it easy to adapt your visualizations for different use cases or output formats (like screen, print, etc.)</p></li><li><p><strong>Maintainability</strong>: If configurations are hard-coded with the data, any change in visual aspects would potentially require changing the data which is not a good practice. Separating them makes maintaining the code easier.</p></li></ul><p>You can load the config with several methods:</p><ul><li>with <code>&lt;script type=&quot;config&quot;&gt;&lt;/script&gt;</code> with the <a href="./embebed.html">configuration embebed</a>.</li><li>with the <code>methods-src</code> for <a href="./external.html">load as resource</a> with the CSV, JSON or JSON5 file.</li></ul><p>In Graphane, the configuration defined is accesibles from the template directives, and also be called from the property <a href="./property.html"><code>.config</code></a>.</p>',6),r=[n];function s(c,d,l,h,u,p){return a(),t("div",null,r)}const m=e(o,[["render",s]]);export{g as __pageData,m as default};
